def solve(order):
    first_store = None
    checks = []
    for index, event in enumerate(order):
        if event.startswith("check"):
            checks.append(index)
        elif event.startswith("store") and first_store is None:
            first_store = index
    if len(checks) >= 2 and (first_store is None or checks[1] < first_store):
        return "twice"
    return "once"
